package alphametics

import (
	"errors"
	"fmt"
	"sort"
	"strings"
)

// Solve solves an alphametics puzzle of the form
// "WORD1 + WORD2 + ... == RESULT" and returns the letter-to-digit
// mapping, or an error if the puzzle has no solution.
func Solve(puzzle string) (map[string]int, error) {
	parts := strings.Split(puzzle, "==")
	if len(parts) != 2 {
		return nil, errors.New("invalid puzzle: expected exactly one '=='")
	}
	addendStrs := strings.Split(parts[0], "+")
	words := make([]string, 0, len(addendStrs)+1)
	for _, a := range addendStrs {
		words = append(words, strings.TrimSpace(a))
	}
	result := strings.TrimSpace(parts[1])
	if len(result) == 0 {
		return nil, errors.New("invalid puzzle: missing result")
	}
	words = append(words, result)

	// Collect distinct letters and coefficients.
	coeff := make(map[rune]int64)
	noZero := make(map[rune]bool)
	for i, w := range words {
		if w == "" {
			return nil, errors.New("invalid puzzle: empty word")
		}
		if len(w) > 1 {
			noZero[rune(w[0])] = true
		}
		place := int64(1)
		sign := int64(1)
		if i == len(words)-1 {
			sign = -1
		}
		for j := len(w) - 1; j >= 0; j-- {
			c := rune(w[j])
			if c < 'A' || c > 'Z' {
				return nil, fmt.Errorf("invalid puzzle: non-letter %q in word %q", c, w)
			}
			coeff[c] += sign * place
			place *= 10
		}
	}

	letters := make([]rune, 0, len(coeff))
	for c := range coeff {
		letters = append(letters, c)
	}
	// Sort by decreasing absolute coefficient for better pruning.
	sort.Slice(letters, func(i, j int) bool {
		return abs64(coeff[letters[i]]) > abs64(coeff[letters[j]])
	})

	if len(letters) > 10 {
		return nil, errors.New("no solution: more than 10 distinct letters")
	}

	assignment := make(map[rune]int, len(letters))
	digitUsed := make([]bool, 10)

	var search func(idx int, sum int64) bool
	search = func(idx int, sum int64) bool {
		if idx == len(letters) {
			return sum == 0
		}
		// Range pruning: the unassigned letters' contributions must
		// be able to bring the running total to zero.
		minRem, maxRem := int64(0), int64(0)
		for k := idx; k < len(letters); k++ {
			c := coeff[letters[k]]
			if c < 0 {
				minRem += 9 * c
			} else {
				maxRem += 9 * c
			}
		}
		if -sum < minRem || -sum > maxRem {
			return false
		}
		c := letters[idx]
		for d := 0; d <= 9; d++ {
			if digitUsed[d] {
				continue
			}
			if d == 0 && noZero[c] {
				continue
			}
			digitUsed[d] = true
			assignment[c] = d
			if search(idx+1, sum+int64(d)*coeff[c]) {
				return true
			}
			digitUsed[d] = false
			delete(assignment, c)
		}
		return false
	}

	if !search(0, 0) {
		return nil, errors.New("no solution")
	}

	res := make(map[string]int, len(letters))
	for c, d := range assignment {
		res[string(c)] = d
	}
	return res, nil
}

func abs64(v int64) int64 {
	if v < 0 {
		return -v
	}
	return v
}
